16	{
17	    /** @param array<int, string> $namespaces */
18	    public static function classNotFoundInNamespaces(
19	        string $className,
20	        array $namespaces,
21	    ): self {
22	        return new self(sprintf(
23	            "The class '%s' was not found in the chain configured namespaces %s",
24	            $className,
25	            implode(', ', $namespaces),
26	        ));
27	    }
28	
29	    /** @param class-string $driverClassName */
30	    public static function pathRequiredForDriver(string $driverClassName): self
31	    {
32	        return new self(sprintf(
33	            'Specifying source file paths to your entities is required when using %s to retrieve all class names.',
34	            $driverClassName,
35	        ));
36	    }
37	
38	    public static function fileMappingDriversRequireConfiguredDirectoryPath(
39	        string|null $path = null,
40	    ): self {
41	        if ($path !== null) {
42	            $path = '[' . $path . ']';
43	        }
44	
45	        return new self(sprintf(
46	            'File mapping drivers must have a valid directory path, ' .
47	            'however the given path %s seems to be incorrect!',
48	            (string) $path,
49	        ));
50	    }
51	
